import{_ as t,o as s,c as i,ag as a}from"./chunks/framework.D1z9wg1y.js";const g=JSON.parse('{"title":"The dotfiles command","description":"","frontmatter":{},"headers":[],"relativePath":"dotfiles-command.md","filePath":"dotfiles-command.md"}'),o={name:"dotfiles-command.md"};function n(d,e,h,c,l,r){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="the-dotfiles-command" tabindex="-1">The <code>dotfiles</code> command <a class="header-anchor" href="#the-dotfiles-command" aria-label="Permalink to &quot;The \`dotfiles\` command&quot;">​</a></h1><p>The dotfiles kit of the harness, <code>examples/dotfiles/</code>, is a chezmoi source with placeholder data. It keeps a private chezmoi source signed and applied on several machines, and it sets each machine up: the tool check, the clones, Julia, the harness at a pinned commit, and the jobs of the harness. On each machine it installs the command <code>dotfiles</code> and the scripts that <code>dotfiles</code> runs, in <code>~/.local/bin</code>.</p><p>The kit is optional. The setup pages for <a href="./setup-macos#dotfiles-optional">macOS</a> and <a href="./setup-linux#dotfiles-optional">Linux</a> work without it.</p><p>The harness never installs these scripts itself. The scripts check and move the pin of the harness, so the checker must not come from the thing that it checks. You copy the kit into a private repository with <a href="./harness-command#dotfiles-kit"><code>harness dotfiles-kit</code></a>, and chezmoi applies that repository on each machine. <a href="#start-a-private-copy">Start a private copy</a> gives the steps.</p><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles update</span></span>
<span class="line"><span>dotfiles check [--full]</span></span>
<span class="line"><span>dotfiles merge &lt;number | branch&gt;</span></span>
<span class="line"><span>dotfiles --help</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>dotfiles</code> is the one front door to the dotfiles scripts. Each subcommand runs the script <code>dotfiles-&lt;subcommand&gt;</code> beside it in <code>~/.local/bin</code>, which does the work and asks its own questions:</p><table tabindex="0"><thead><tr><th style="text-align:left;">subcommand</th><th style="text-align:left;">runs</th><th style="text-align:left;">where</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#dotfiles-update"><code>update</code></a></td><td style="text-align:left;"><code>dotfiles-update</code></td><td style="text-align:left;">every host</td></tr><tr><td style="text-align:left;"><a href="#dotfiles-check"><code>check</code></a></td><td style="text-align:left;"><code>dotfiles-check</code></td><td style="text-align:left;">every host</td></tr><tr><td style="text-align:left;"><a href="#dotfiles-merge"><code>merge</code></a></td><td style="text-align:left;"><code>dotfiles-merge</code></td><td style="text-align:left;">the template host only</td></tr></tbody></table><p><code>dotfiles --help</code> prints the three subcommands and where each one runs. No subcommand, a subcommand that is not in the list, or a <code>merge</code> without exactly one argument prints the usage line and exits 2.</p><p>The <em>template host</em> is the one machine that signs: the key <code>template_host</code> of <code>.chezmoidata/machines.toml</code> names it. Only it receives <code>dotfiles-merge</code> and git&#39;s <code>user.signingkey</code>.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><h3 id="dotfiles-update" tabindex="-1"><code>dotfiles update</code> <a class="header-anchor" href="#dotfiles-update" aria-label="Permalink to &quot;\`dotfiles update\`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles update</span></span></code></pre></div><p>Brings the applied source <code>~/.local/share/chezmoi</code> to <code>origin/main</code>, and applies it. It replaces <code>chezmoi update</code> on every host. It stops when standard input is not a terminal. Then it runs <code>git fetch</code>, and checks every commit on the first-parent path from <code>HEAD</code> to <code>origin/main</code>, as <a href="#the-update-path">The update path</a> says. When each commit passes, it merges <code>--ff-only</code>, shows <code>chezmoi diff</code>, asks <code>y/N</code>, and applies on <code>y</code>. A check that fails names each commit that fails, merges nothing and applies nothing: <code>HEAD</code> stays where it was.</p><p>An answer other than <code>y</code> or <code>Y</code> applies nothing, and the source stays at the merged commit. So the next <code>dotfiles update</code> finds nothing new. To review the change again, run <code>chezmoi diff</code> and then <code>chezmoi apply</code> yourself.</p><p><a href="#the-review">The review</a> must be read to its end. When you quit the pager early, it stops before the question, applies nothing, and prints one line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles-update: you quit the review early; the source is at &lt;commit&gt; and nothing is applied. Run chezmoi diff, read it to its end, then run chezmoi apply.</span></span></code></pre></div><p><strong>Exit status:</strong> 0 when nothing is new, or after the question, whatever the answer; 1 when standard input is not a terminal, when the check fails: a commit without a good signature by a listed key, an <code>origin/main</code> that is not a fast-forward of <code>HEAD</code>, or an <code>allowed_signers</code> that is missing or lists no key, and when you quit the review early. When <code>git</code>, <code>chezmoi</code> or the pager fails, it stops with the status of that command.</p><p><strong>Reads:</strong> <code>~/.config/git/allowed_signers</code> as it is applied. <strong>Writes:</strong> the source <code>~/.local/share/chezmoi</code>, and, after <code>y</code>, the files that chezmoi applies.</p><p><strong>Where to run it:</strong> in your own terminal, on every host. A session has no terminal for the question, and the <a href="./security">sandbox</a> does not let it write the source.</p><h3 id="dotfiles-check" tabindex="-1"><code>dotfiles check</code> <a class="header-anchor" href="#dotfiles-check" aria-label="Permalink to &quot;\`dotfiles check\`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles check [--full]</span></span></code></pre></div><p>Checks the setup of this machine. It prints one line for each check in the form of <a href="./harness-command#doctor"><code>harness doctor</code></a>, <code>PASS</code>, <code>WARN</code>, <code>FAIL</code> or <code>SKIP</code> with the name of the check and a detail, then a count line. The checks, in order:</p><ul><li><code>harness doctor</code>, with <code>--full</code> when it is given; its check lines pass through;</li><li><code>chezmoi verify --exclude=scripts</code> passes, and <code>chezmoi diff --exclude=scripts</code> is empty;</li><li>the head of <code>~/.local/share/chezmoi</code> carries a good signature by a key of the applied <code>allowed_signers</code>, as <code>dotfiles update</code> checks each commit;</li><li>the head is <code>origin/main</code> as the last fetch saw it, and <code>WARN</code> when it is behind;</li><li>the <code>HEAD</code> of <code>~/Research/Harness</code> is <code>harness_commit</code>, or contains it on the template host;</li><li>each code file of the kit in the source equals the kit of the harness at <code>harness_commit</code>. A file that differs is a <code>WARN</code>, not a <code>FAIL</code>, because a machine on an older pin has an older kit. The check is <code>SKIP</code> when the harness checkout lacks that commit or that commit has no kit;</li><li>with <code>--full</code>, Revise loads on each <code>X.Y</code> channel of the host&#39;s <code>julia_channels</code>, and the host&#39;s GPU package (<code>Metal</code>, <code>CUDA</code> or <code>AMDGPU</code>) says that it is functional.</li></ul><p>It is read-only: it needs no terminal, asks nothing, fetches nothing and writes no file. With <code>--full</code>, Julia can still precompile a stale package into its depot.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--full</code></td><td style="text-align:left;">also run <code>harness doctor --full</code>, and the checks of Julia</td></tr></tbody></table><p><strong>Exit status:</strong> 1 when a line is <code>FAIL</code>, else 0. A <code>WARN</code> or a <code>SKIP</code> does not count. 2 on a usage error.</p><p><strong>Reads:</strong> the source, <code>~/.config/git/allowed_signers</code>, the harness checkout <code>~/Research/Harness</code>, and <code>examples/dotfiles/kit.toml</code> at <code>harness_commit</code>. <strong>Writes:</strong> nothing.</p><p><strong>Where to run it:</strong> in a plain terminal, on every host, after each apply. In a session, the sandbox can refuse a <code>chezmoi</code> or <code>julia</code> command: a command that does not pass there is <code>SKIP</code>, as in <code>harness doctor</code>.</p><h3 id="dotfiles-merge" tabindex="-1"><code>dotfiles merge</code> <a class="header-anchor" href="#dotfiles-merge" aria-label="Permalink to &quot;\`dotfiles merge\`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles merge &lt;number | branch&gt;</span></span></code></pre></div><p>Merges a reviewed branch into <code>main</code> of the source. A number, digits only, is a pull request or a merge request of the source&#39;s <code>origin</code>: <code>gh</code> names its branch for an <code>origin</code> on <code>github.com</code>, and <code>glab</code> for any other host. A request that is not open stops <code>dotfiles merge</code> before the merge. Any other argument is a branch name.</p><p>Then <code>dotfiles-merge &lt;branch&gt;</code> stops when standard input is not a terminal, when the host data gives no <code>signing_key</code>, when the source has local changes, untracked files included, and when its <code>HEAD</code> is not <code>main</code> at <code>origin/main</code>. It prints <code>git log --first-parent main..origin/&lt;branch&gt;</code> and the diff <code>main...origin/&lt;branch&gt;</code>, and asks <code>y/N</code>. On <code>y</code>, it makes a <code>--no-ff</code> merge signed by the <code>signing_key</code>, checks the merge as <code>dotfiles update</code> checks a commit, and pushes <code>main</code>. Then it shows <code>chezmoi diff</code>, asks again, and applies on <code>y</code>.</p><p>A conflict or a failed signature leaves no merge. A merge that fails the check is undone. A refused push leaves the local merge, names it, and applies nothing.</p><p>Each part of <a href="#the-review">the review</a> must be read to its end. When you quit the pager of the log or the diff early, it stops before the first question, and nothing is merged, signed or pushed. When you quit the pager of <code>chezmoi diff</code> early, the merge is already pushed, and nothing is applied. Each stop prints one line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotfiles-merge: you quit the review early; nothing is merged. Run dotfiles merge &lt;branch&gt; again and read the review to its end.</span></span>
<span class="line"><span>dotfiles-merge: you quit the review early; the merge &lt;commit&gt; is pushed and nothing is applied. Run chezmoi diff, read it to its end, then run chezmoi apply.</span></span></code></pre></div><p><strong>Exit status:</strong> 0 when <code>main</code> already contains the branch, when the answer to the first question is not <code>y</code>, or after the second question, whatever the answer; 1 when a stop above applies, on a host without <code>dotfiles-merge</code>, when the request is not open or not found, when the remote has no such branch, when the merge, its signature or its check fails, when the push is refused, and when you quit the review early; 2 on a usage error.</p><p><strong>Reads:</strong> <code>~/.config/git/allowed_signers</code>, and the <code>signing_key</code> and <code>sk_provider</code> of the host data, which chezmoi writes into the script when it applies it. <strong>Writes:</strong> the source, the branch <code>main</code> of its <code>origin</code>, and, after the second <code>y</code>, the files that chezmoi applies.</p><p><strong>Where to run it:</strong> in your own terminal, on the template host only, after you read the pull request or the merge request. A signing key in hardware asks for a touch: touch it only during a <code>dotfiles merge</code> of your own.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotfiles</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # pull request or merge request 12 of the origin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotfiles</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kit-update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # the branch kit-update</span></span></code></pre></div><h2 id="the-review" tabindex="-1">The review <a class="header-anchor" href="#the-review" aria-label="Permalink to &quot;The review&quot;">​</a></h2><p><code>dotfiles update</code> and <code>dotfiles merge</code> show each part of the review, the log, the diff and <code>chezmoi diff</code>, in git&#39;s pager: <code>GIT_PAGER</code>, then <code>core.pager</code>, then <code>PAGER</code>, then <code>less</code>, with <code>LESS=FRX</code> and <code>LV=-c</code> when they are not set, as git runs it. The pager setting of chezmoi does not count here.</p><p>A pager that quits before the command has written all of its output breaks the pipe, and the script stops with the line that the subcommand names. A review that fits in the pipe&#39;s buffer, about 64 KB, is written before you quit, so quitting it early does not stop the script. With <code>LESS=FRX</code>, <code>less</code> quits by itself at the end of a review that fits on one screen; a <code>LESS</code> without <code>F</code>, such as the <code>-R</code> that oh-my-zsh sets, waits for <code>q</code> at the end.</p><h2 id="the-update-path" tabindex="-1">The update path <a class="header-anchor" href="#the-update-path" aria-label="Permalink to &quot;The update path&quot;">​</a></h2><p>A Git host does not always let you refuse an unsigned commit, so each machine checks the signatures itself. A machine applies <code>main</code> only when every commit on the first-parent path from its applied <code>HEAD</code> to <code>origin/main</code> carries a good signature, <code>%G?</code> is <code>G</code>, by a key of its <code>~/.config/git/allowed_signers</code>, <strong>as applied before the update</strong>. An incoming commit that adds a key to the source&#39;s copy of <code>allowed_signers</code> does not make that key count.</p><ul><li><strong>Only an SSH signature counts.</strong> The check reads <code>%G?</code> and the principal, not only the exit status of <code>git verify-commit</code>. An OpenPGP or an X.509 signature never gives <code>G</code> here, whichever keys the host&#39;s <code>gpg</code> trusts.</li><li><strong>One machine signs.</strong> The template <code>.chezmoitemplates/gitconfig-signing</code>, which your <code>.gitconfig</code> template includes, writes the signing settings of git. With it, only the template host&#39;s <code>~/.gitconfig</code> names the key in <code>user.signingkey</code>. Every host has <code>gpg.format = ssh</code> and <code>gpg.ssh.allowedSignersFile</code>, and no host has <code>commit.gpgsign</code>, so a commit is signed only with an explicit <code>-S</code>.</li><li><strong>A key that needs a provider</strong>, such as a key in the Secure Enclave of a Mac, gets its <code>SSH_SK_PROVIDER</code> from <code>sk_provider</code> in <code>dotfiles merge</code> alone. No other file of the kit sets it, so a <code>git commit -S</code> that a session starts finds no provider and cannot sign. The prompt of such a key cannot name the signature that it is for; the line before it, <code>dotfiles-merge: &lt;key&gt; now signs the merge of origin/&lt;branch&gt; (&lt;commit&gt;) into main.</code>, names it.</li><li><strong>The harness moves only with the source.</strong> <code>harness_commit</code> in <code>.chezmoidata/machines.toml</code> is the commit of the harness for every machine. When it changes, the harness script of <code>.chezmoiscripts/</code> checks out that commit in <code>~/Research/Harness</code> and runs <code>harness setup --yes</code>, which runs <code>harness install --apply</code>. On the template host, where <code>~/Research/Harness</code> is the development checkout, it moves no checkout, and stops when <code>HEAD</code> does not contain the commit. So a machine moves to a new harness only through a reviewed and signed change of that line.</li></ul><h3 id="a-new-machine" tabindex="-1">A new machine <a class="header-anchor" href="#a-new-machine" aria-label="Permalink to &quot;A new machine&quot;">​</a></h3><p>A new machine gets its <code>allowed_signers</code> by hand, before <code>chezmoi init</code>. Write the line of the signing key into <code>~/.config/git/allowed_signers</code>, in the form of the ALLOWED SIGNERS section of <code>ssh-keygen(1)</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>owner@example.org namespaces=&quot;git&quot; ssh-ed25519 &lt;the public key&gt;</span></span></code></pre></div><p>Compare its fingerprint with the fingerprint that the README of your private copy names. On the template host, <code>ssh-keygen -l -f</code> of the key&#39;s <code>.pub</code> file prints it.</p><p><code>chezmoi init</code> clones your private repository before chezmoi applies any <code>~/.gitconfig</code>, and the first apply clones the remotes of <code>[remotes]</code>. So git needs credentials for each of their hosts first: an SSH key that the host accepts, for an SSH URL, or a credential helper, for an HTTPS URL. A helper goes into <code>~/.gitconfig</code>, such as <code>gh auth login</code> and then <code>gh auth setup-git</code> for a host of <code>gh</code>, or, for a host of <code>glab</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">glab</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hostname</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential.https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.helper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;!glab auth git-credential&#39;</span></span></code></pre></div><p>When your <code>.gitconfig</code> template writes the same helper, the first <code>chezmoi diff</code> shows <code>~/.gitconfig</code> as replaced.</p><p>Then run <code>chezmoi init &lt;repository&gt;</code> without <code>--apply</code>, and check the head of the source. No <code>~/.gitconfig</code> names <code>allowed_signers</code> before the first apply, so the command names it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/chezmoi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.ssh.allowedSignersFile=&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.config/git/allowed_signers&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.openpgp.program=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.x509.program=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%G? %GS&#39;</span></span></code></pre></div><p>It must print <code>G</code> and the principal, such as <code>G owner@example.org</code>. Then read the whole <code>chezmoi diff</code>, and run <code>chezmoi apply</code>. Before any file changes, the apply runs the tool check of the kit: when a tool is missing, it names the tool and stops the apply; it installs nothing. It requires <code>git</code>, <code>zsh</code>, <code>curl</code>, <code>python3</code> 3.11 or later, <code>lsof</code>, <code>rtk</code>, <code>juliaup</code>, <code>gh</code> and <code>glab</code> on every host, and <code>bwrap</code>, <code>socat</code> and <code>secret-tool</code> on Linux. So a host needs <code>glab</code> even when all its remotes are on GitHub, and <code>gh</code> even when none is: install both, or the first apply stops. From then on, the machine updates with <code>dotfiles update</code> only.</p><h3 id="the-first-signed-commit" tabindex="-1">The first signed commit <a class="header-anchor" href="#the-first-signed-commit" aria-label="Permalink to &quot;The first signed commit&quot;">​</a></h3><p><code>dotfiles merge</code> is not on any machine before the first apply, so the first signed commit of <code>main</code> is made by hand, on the template host, in a terminal, in your clone. Write the line of your key into <code>~/.config/git/allowed_signers</code>, as <a href="#a-new-machine">A new machine</a> shows, and set the three lines that the template writes once it is applied:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.signingkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> signing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.ssh.allowedSignersFile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/git/allowed_signers</span></span></code></pre></div><p>In a new private copy, <code>main</code> has no commit yet: commit the kit on <code>main</code>, signed. In a copy whose <code>main</code> exists, bring <code>main</code> up to <code>origin/main</code>, and merge the branch, signed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;message&gt;&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # a new copy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-ff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a copy whose main exists</span></span></code></pre></div><p>Then check the signature, and push:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.openpgp.program=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg.x509.program=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%G? %GS&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>The <code>show</code> must print <code>G</code> and the principal before the push. A key that needs a provider gets it on the command that signs alone, as <code>SSH_SK_PROVIDER=&lt;provider&gt; git commit -S …</code>. From then on, merge with <code>dotfiles merge</code> only.</p><h2 id="the-data-of-machines-toml" tabindex="-1">The data of <code>machines.toml</code> <a class="header-anchor" href="#the-data-of-machines-toml" aria-label="Permalink to &quot;The data of \`machines.toml\`&quot;">​</a></h2><p><code>.chezmoidata/machines.toml</code> is a seed file of the kit: <code>harness dotfiles-kit</code> copies it once, and then it belongs to your copy. Each template that reads the host table stops with chezmoi&#39;s <code>fail</code> on a hostname that the table does not list, so a new machine needs its entry before its first apply.</p><table tabindex="0"><thead><tr><th style="text-align:left;">key</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>harness_commit</code></td><td style="text-align:left;">the commit of the harness for every machine, 40 hex digits</td></tr><tr><td style="text-align:left;"><code>template_host</code></td><td style="text-align:left;">the hostname of the one machine that signs</td></tr><tr><td style="text-align:left;"><code>[remotes]</code></td><td style="text-align:left;">the clone URLs of <code>claude</code> (<code>~/.claude</code>), <code>environment</code> (<code>~/Research/Environment</code>), <code>harness</code> (<code>~/Research/Harness</code>) and <code>meta</code>, the meta repository, whose work tree is <code>~/Research</code></td></tr><tr><td style="text-align:left;"><code>[machines.&lt;hostname&gt;]</code></td><td style="text-align:left;">one table for each machine, under its <code>hostname -s</code></td></tr><tr><td style="text-align:left;"><code>os</code></td><td style="text-align:left;"><code>darwin</code> or <code>linux</code></td></tr><tr><td style="text-align:left;"><code>arch</code></td><td style="text-align:left;">the machine&#39;s <code>uname -m</code></td></tr><tr><td style="text-align:left;"><code>gpu</code></td><td style="text-align:left;"><code>metal</code>, <code>cuda</code>, <code>amdgpu</code> or <code>none</code>: the GPU package that Julia gets</td></tr><tr><td style="text-align:left;"><code>julia_channels</code></td><td style="text-align:left;">the juliaup channels to install</td></tr><tr><td style="text-align:left;"><code>julia_default</code></td><td style="text-align:left;">the default channel among them</td></tr><tr><td style="text-align:left;"><code>signing_key</code></td><td style="text-align:left;">the key that signs the merges of <code>dotfiles merge</code>, as git&#39;s <code>user.signingkey</code> reads it; only the template host reads it</td></tr><tr><td style="text-align:left;"><code>sk_provider</code></td><td style="text-align:left;">the <code>SSH_SK_PROVIDER</code> that the signing key needs, such as <code>/usr/lib/ssh-keychain.dylib</code> for a key in the Secure Enclave of a Mac; empty for a key that needs none</td></tr></tbody></table><p>The keys from <code>os</code> to <code>sk_provider</code> are the keys of each <code>[machines.&lt;hostname&gt;]</code> table. <code>.chezmoidata/julia.toml</code>, a seed too, names the Julia packages of every host, each with its minimum channel.</p><h2 id="start-a-private-copy" tabindex="-1">Start a private copy <a class="header-anchor" href="#start-a-private-copy" aria-label="Permalink to &quot;Start a private copy&quot;">​</a></h2><ol><li><p>Make an empty private repository, and clone it to a directory of your own, such as <code>~/src/dotfiles</code>. Do not use the source that chezmoi applies, <code>~/.local/share/chezmoi</code>: <code>harness dotfiles-kit</code> refuses it.</p></li><li><p>List the files of the kit that the clone lacks, then copy them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotfiles-kit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/src/dotfiles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotfiles-kit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/src/dotfiles</span></span></code></pre></div></li><li><p>Write your own values into the seed files: your machines, <code>template_host</code>, the remotes and <code>harness_commit</code> in <code>.chezmoidata/machines.toml</code>; the public key of your signing key in <code>dot_config/git/allowed_signers</code>; and your profile and model tables in <code>dot_config/research-harness/</code>. Write a <code>README.md</code> that names the fingerprint of the signing key, which <code>ssh-keygen -l -f</code> of the key&#39;s <code>.pub</code> file prints, and links this page: each <a href="#a-new-machine">new machine</a> compares with it. The kit&#39;s <code>.chezmoiignore</code> keeps <code>README.md</code> off the machines.</p></li><li><p>Add your own files beside the kit&#39;s. The kit does not own <code>~/.gitconfig</code>: your own <code>dot_gitconfig.tmpl</code> includes the signing settings of git with this line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ template &quot;gitconfig-signing&quot; . }}</span></span></code></pre></div><p>The ignore lines of your copy alone go into <code>.chezmoitemplates/chezmoiignore.local</code>.</p></li><li><p>Run the five tests of the kit in <code>tests/</code> of the clone, such as <code>python3 tests/render-check.py</code>; <a href="./development#the-pre-push-hook">development.md</a> names them. They need Python 3.11 or later and chezmoi. <code>script-check.py</code> also reads <code>~/Research/Harness</code> at <code>harness_commit</code>.</p></li><li><p>Make <a href="#the-first-signed-commit">the first signed commit</a>, and push it. Then set up each machine as <a href="#a-new-machine">A new machine</a> says.</p></li></ol><p>A <em>code</em> file of the kit stays identical to the kit, and a <em>seed</em> file is yours once it is there. To move to a new harness, change <code>harness_commit</code>, and run <code>harness dotfiles-kit</code> again from a harness checkout at that commit: it lists each code file that changed. Until you copy them, <code>dotfiles check</code> reports the kit as a <code>WARN</code>.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">file</th><th style="text-align:left;">what it is</th></tr></thead><tbody><tr><td style="text-align:left;"><code>~/.local/bin/dotfiles</code></td><td style="text-align:left;">the driver</td></tr><tr><td style="text-align:left;"><code>~/.local/bin/dotfiles-update</code>, <code>dotfiles-check</code></td><td style="text-align:left;">the scripts of every host</td></tr><tr><td style="text-align:left;"><code>~/.local/bin/dotfiles-merge</code></td><td style="text-align:left;">the merge script, on the template host only</td></tr><tr><td style="text-align:left;"><code>~/.local/share/chezmoi</code></td><td style="text-align:left;">the applied source, which <code>chezmoi init</code> clones, and only <code>dotfiles update</code> and <code>dotfiles merge</code> move</td></tr><tr><td style="text-align:left;"><code>~/.config/git/allowed_signers</code></td><td style="text-align:left;">the keys whose signatures count, as applied</td></tr><tr><td style="text-align:left;"><code>.chezmoidata/machines.toml</code></td><td style="text-align:left;">the data of the source; see <a href="#the-data-of-machines-toml">The data of <code>machines.toml</code></a></td></tr><tr><td style="text-align:left;"><code>.chezmoitemplates/dotfiles-update-steps.sh</code></td><td style="text-align:left;">the steps that <code>dotfiles-update</code> and <code>dotfiles-merge</code> share: the terminal test, the question, the check, and the review and apply</td></tr><tr><td style="text-align:left;"><code>.chezmoitemplates/dotfiles-signature.sh</code></td><td style="text-align:left;">the signature test of one commit, which <code>dotfiles-check</code> uses too</td></tr><tr><td style="text-align:left;"><code>.chezmoitemplates/gitconfig-signing</code></td><td style="text-align:left;">the signing settings of git, for your <code>.gitconfig</code> template</td></tr><tr><td style="text-align:left;"><code>kit.toml</code></td><td style="text-align:left;">each file of the kit and its class, <code>code</code> or <code>seed</code></td></tr></tbody></table>`,74)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
